    for color, cells in coords.items():
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        border = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                  if r in (r0, r1) or c in (c0, c1)}
        if set(cells) == border:
            boxes.append((color, r0, r1, c0, c1))
    if boxes:
        frame_color, r0, r1, c0, c1 = boxes[0]
        # The 3x3 marker with a background center indicates its border color as fill.
        fill = None
