            rr0, rr1 = min(r for r, c in cells), max(r for r, c in cells)
            cc0, cc1 = min(c for r, c in cells), max(c for r, c in cells)
            if (rr1 - rr0, cc1 - cc0) == (2, 2) and len(cells) == 8:
